"""Render results.json as Markdown tables (results/MATRICES.md). Generated: do not edit by hand."""


def f(x, d=0):
    if x is None:
        return '—'
    if isinstance(x, str):
        return x
    if abs(x) >= 1e5 or (0 < abs(x) < 1e-3):
        return f'{x:.2e}'
    if x != 0 and abs(x) < 10**(-d)*10:      # keep two significant figures where the fixed decimals would hide the value
        return f'{x:.2g}' if abs(x) >= 0.01 else f'{x:.2e}'
    return f'{x:,.{d}f}'


def table(head, rows):
    out = ['| '+' | '.join(head)+' |', '|'+'|'.join(['---']*len(head))+'|']
    out += ['| '+' | '.join(r)+' |' for r in rows]
    return '\n'.join(out)+'\n'


def render(o):
    s = ['# Four-burn study: generated tables', '', f"Scenario {o['scenario']} ({o['date']}). Generated by `run.py`; every number "
         'below is reproducible from `scenarios/v1.toml`, `data/wayfarer_3d.toml` and the as-built tank evidence.', '']
    a = o['canon_audit']; r = a['reproduced']
    s += ['## Canon audit', '', table(['Quantity', 'This model', 'Canon (p1_operating_point.json)'], [
        ['Departure / end mass (t)', f"{f(r['departure_t'])} / {f(r['end_t'])}", '4,426 / 1,629'],
        ['Propellant, four burns (t)', f(r['propellant_t']), '2,797'],
        ['He-3 / D / H (t)', ' / '.join(f(r['species_t'][k]) for k in ('helium_3', 'deuterium', 'hydrogen')),
         ' / '.join(f(r['canon_species_t'][k]) for k in ('helium_3', 'deuterium', 'hydrogen'))],
        ['Fused / recovered / lost unburned (t)', f"{f(r['fused_t'])} / {f(r['recovered_t'])} / {f(r['lost_t'])}", '—']])]
    sh = a['shortfall_147t']; tl = a['tank_law']
    s += [f"147 t: braking from cruise at the pass-5 burnout mass {f(sh['burnout_t'])} t needs {f(sh['braking_need_t'])} t; the reserve was "
          f"{f(sh['reserve_t'])} t, short {f(sh['shortfall_t'])} t. {sh['status']}", '',
          f"Tank law: the operating point books {f(tl['model_tank_t'])} t of tanks (0.15 x propellant); the as-built farm is "
          f"{f(tl['as_built_tank_t'])} t (+{f(tl['difference_t'])} t). Closing the four burns with the as-built mass needs "
          f"{f(tl['extra_propellant_t'])} t more propellant (departure {f(tl['departure_t_as_built'])} t).", '']
    for name, key in (('canon split', 'tanks_canon_split'), ('as-built closure', 'tanks_as_built_closure')):
        t = a[key]
        s += [f'Tank check, {name}:', '', table(['Species', 'Required m3', 'Existing m3', 'Surplus m3', 'Use'], [
            [k, f(t['required_m3'][k]), f(t['existing_m3'][k]), f(t['surplus_m3'][k]), f"{t['ratio'][k]*100:.1f} %"]
            for k in ('helium_3', 'deuterium', 'hydrogen')]), f"Outcome: {t['outcome']}", '']
    s += ['## Matrix A: acceleration versus time (0.016 c per burn, relativistic constant proper acceleration)', '', table(
        ['Accel (g)', 'Burn (days)', 'Proper (days)', 'Newtonian error', 'Accel distance (AU)', 'Four burns (days)', 'Four burns (years)',
         'Min destination (AU)', 'Jet power at canon ve (MW/t)', 'Const thrust from departure (days)'],
        [[f(x['accel_g'], 3), f(x['burn_days'], 2), f(x['burn_proper_days'], 2), f"{x['newtonian_time_error']:.1e}",
          f(x['accel_distance_AU'], 2), f(x['four_burn_days'], 1), f(x['four_burn_years'], 3), f(x['min_destination_AU'], 1),
          f(x['jet_power_MW_per_t_at_canon_ve'], 1), f(x['const_thrust_from_departure_days'], 2)] for x in o['matrix_A']])]
    for name, rows in o['matrix_B'].items():
        s += [f'## Matrix B: exhaust velocity versus propellant ({name})', '', table(
            ['ve (km/s)', 'R per burn', 'R four burns', 'Burn 1 propellant, fixed end (t)', 'Propellant, fixed end (t)',
             'Departure, fixed end (t)', 'Tank loop gain k(R4-1)', 'Propellant with tanks (t)', 'Tanks (t)', 'Departure with tanks (t)'],
            [[f(x['ve_km_s']), f(x['mass_ratio_per_burn'], 3), f(x['mass_ratio_total'], 2), f(x['first_burn_propellant_t_fixed_end']),
              f(x['propellant_t_fixed_end']), f(x['departure_t_fixed_end']), f(x['tank_feedback_gain'], 2), f(x['propellant_t_with_tanks']),
              f(x['tank_t']), f(x['departure_t_with_tanks'])] for x in rows])]
    mc = o['matrix_C']
    s += ['## Matrix C: propulsion power', '', f"Directed efficiency: canon {mc['eta']['canon']}, continuous central {mc['eta']['continuous_central']:.3f}, "
          f"pulsed central {mc['eta']['pulsed_central']:.3f}. Heat fraction of fusion power: canon 4e-5, continuous "
          f"{mc['heat_fraction']['continuous_central']:.3f}, pulsed {mc['heat_fraction']['pulsed_central']:.4f}.", '', table(
        ['Case', 'Mass (t)', 've (km/s)', 'Accel (g)', 'Thrust (MN)', 'mdot (kg/s)', 'Jet (TW)', 'Fusion canon (TW)', 'Fusion cont. (TW)',
         'Fusion pulsed (TW)', 'Heat canon (GW)', 'Heat cont. (GW)', 'Heat pulsed (GW)'],
        [[x['case'], f(x['mass_t']), f(x['ve_km_s']), f(x['accel_g'], 3), f(x['thrust_MN'], 2), f(x['mass_flow_kg_s'], 3), f(x['jet_power_TW'], 3),
          f(x['fusion_TW_canon_eta0.8'], 2), f(x['fusion_TW_continuous'], 2), f(x['fusion_TW_pulsed'], 2), f(x['heat_GW_canon_4e-5'], 2),
          f(x['heat_GW_continuous'], 1), f(x['heat_GW_pulsed'], 1)] for x in mc['rows']])]
    s += ['## Sustaining 1 g', '', table(['Drive', 've (km/s)', 'Closes?', 'Departure (t)', 'Fusion (TW)', 'Drive specific mass (kg/W jet)',
                                         'Needed for 1 g, zero payload (kg/W jet)', 'Gap', 'Note'],
        [[f"{x['arch']} {x['tier']}", f(x['ve_km_s']), 'yes' if x['closes'] else 'no', f(x['departure_t']), f(x['fusion_TW'], 0),
          f(x['alpha_jet_kg_per_W']), f(x['alpha_needed_zero_payload_kg_per_W']), f(x['gap_factor'], 0) if x['gap_factor'] else '—',
          x['reason'][:70]] for x in o['one_g']])]
    s += ['## Highest departure acceleration that closes', '', table(['Drive', 'Best ve (km/s)', 'a0 limit (g)'],
        [[k, f(v['ve_km_s']) if v else '—', f(v['a0_limit_g']) if v else 'no closure'] for k, v in o['accel_limit'].items()])]
    s += ['## Pareto fronts (shortest four-burn time per departure-mass cap, 860 t payload)', '']
    for k, v in o['existing_payload'].items():
        if not v['front']:
            s += [f"- **{k}**: no closure. {'; '.join(x for x in (v['reason'] or []) if x)}", '']
            continue
        s += [f'**{k}**', '', table(['Departure (t)', 've (km/s)', 'a0 (g)', 'Fusion (TW)', 'Burn time (y)', 'Propellant (t)', 'He-3 (t)',
                                     'Drive (t)', 'Radiators (t)', 'Tanks (t)'],
            [[f(p['departure_t']), f(p['ve_km_s']), f(p['a0_g']), f(p['fusion_power_TW'], 3), f(p['burn_time_years'], 1), f(p['propellant_t']),
              f(p['species_t']['helium_3']), f(p['drive_t']), f(p['radiator_t']), f(p['tank_t'])] for p in v['front']])]
    s += ['## Matrix D: tank comparison', '', table(['Configuration', 'He-3 / D / H (t)', 'Required m3 He-3 / D / H', 'Existing m3',
                                                    'Use (%)', 'L-vessel equiv.', 'Farm length (m)', 'Axial at 1.5 g (MN, x Q45)',
                                                    'Cooling (MW)', 'Tanks (t)', 'Outcome'],
        [[x['config'], ' / '.join(f(x['species_t'][k]) for k in ('helium_3', 'deuterium', 'hydrogen')),
          ' / '.join(f(x['required_m3'][k]) for k in ('helium_3', 'deuterium', 'hydrogen')),
          ' / '.join(f(x['existing_m3'][k]) for k in ('helium_3', 'deuterium', 'hydrogen')),
          ' / '.join(f(x['ratio'][k]*100) for k in ('helium_3', 'deuterium', 'hydrogen')), f(x['vessels_L_equivalent'], 1),
          f(x['farm_length_m']), f"{f(x['axial_load_MN_1_5g'])} ({x['axial_vs_existing']:.1f}x)", f(x['cooling_MW'], 2), f(x['tank_t']),
          x['outcome']] for x in o['matrix_D']])]
    s += ['## Matrix E: integrated architecture comparison', '', table(
        ['Design', 've (km/s)', 'Fusion (TW)', 'eta jet', 'Hot heat / fusion', 'Warm heat / fusion', 'Radiators (t, km2)', 'Propellant (t)',
         'Dry (t)', 'Departure (t)', 'a0 (g)', 'Burn time (y)', 'He-3 (t)', 'Class'],
        [[x['design'], f(x['ve_km_s']), f(x['fusion_TW'], 3), f(x['eta_jet'], 3), f(x['hot_heat_fraction']), f(x['warm_heat_fraction']),
          f"{f(x['radiator_t'])} ({f(x['radiator_km2'], 2)})", f(x['propellant_t']), f(x['dry_t']), f(x['departure_t']), f(x['a0_g']),
          f(x['burn_time_years'], 1), f(x['helium_3_t']), x['classification']] for x in o['matrix_E']])]
    s += ['## Mass cases (owner brief section 5)', '']
    for k, v in o['mass_cases'].items():
        if v is None:
            s += [f'- {k}: no closure', '']
            continue
        if 'rows' in v:
            s += [f'**{k}** ({v["note"]})', '', table(['ve (km/s)', 'Departure (t)', 'Final (t)', 'Burn 1-4 propellant (t)', 'Total (t)',
                                                         'Fraction', 'Tanks at 0.15 (t)', 'Reserve 2 % (t)', 'Thrust at 1 g (MN)',
                                                         'Jet power at 1 g (TW)', 'Burn at 1 g (d)', 'Const-thrust burns (d)'],
                [[f(x['ve_km_s']), f(x['departure_t']), f(x['final_t']), ' / '.join(f(y) for y in x['burn_propellant_t']), f(x['propellant_t']),
                  f(x['propellant_fraction'], 3), f(x['tank_t_at_0.15']), f(x['reserve_t_at_2pct']), f(x['departure_thrust_MN_1g'], 1),
                  f(x['departure_jet_TW_1g'], 0), f(x['burn_days_1g'], 2), ' / '.join(f(y, 2) for y in x['burn_days_const_thrust_1g_departure'])]
                 for x in v['rows']])]
        else:
            s += [f'**{k}**', '', table(['Departure (t)', 'End (t)', 'Payload+drive+radiators+tanks (t)', 'Reserve (t)', 'Burn 1-4 propellant (t)',
                                         'Fraction', 'Thrust (MN)', 'Jet / fusion (TW)', 'Burns (days)', 'Total (y)'],
                [[f(v['departure_t']), f(v['end_t']), f"{f(v['dry_t']-v['drive_t']-v['radiator_t']-v['tank_t'])} + {f(v['drive_t'])} + {f(v['radiator_t'])} + {f(v['tank_t'])}",
                  f(v['reserve_t']), ' / '.join(f(y) for y in v['burn_propellant_t']), f(v['propellant_t']/v['departure_t'], 3), f(v['thrust_MN'], 3),
                  f"{f(v['jet_power_TW'], 3)} / {f(v['fusion_power_TW'], 3)}", ' / '.join(f(y) for y in v['burn_days']), f(v['burn_time_years'], 1)]])]
    s += ['## Fuel ratio and plasma temperature (continuous core energy partition)', '', table(
        ['He-3:D', 'He-3 mass share', 'Ti (keV)', 'Te/Ti', 'Brems', 'Neutron', 'Charged', 'Power density (rel.)'],
        [[f(x['he3_to_d'], 2), f(x['he3_mass_share'], 3), f(x['Ti_keV']), f(x['Te_over_Ti'], 2), f(x['brems'], 3), f(x['neutron'], 3),
          f(x['charged'], 3), f(x['power_density_rel'], 2)] for x in o['fuel_ratio']])]
    s += ['## Sensitivity (one parameter swapped to its optimistic or pessimistic tier; four-burn time in years)', '']
    for k, v in o['sensitivity'].items():
        b = v['base']
        s += [f"**{k}** base {f(b['burn_time_years'], 1)} y" if b else f'**{k}** no base closure', '', table(['Parameter', 'Optimistic', 'Pessimistic'],
            [[x['parameter'], f(x.get('optimistic'), 1), f(x.get('pessimistic'), 1)] for x in v['rows']])]
    if o.get('dose'):
        s += ['## Crew dose from the drive (unshielded, 150 m)', '', table(['Design', 'Neutron power (W)', 'Unshielded (Sv/h)', 'Attenuation for 20 mSv/y',
                                                                           'LiH (m)'],
            [[k, f(v['neutron_W']), f(v['unshielded_Sv_per_h']), f(v['attenuation_needed']), f(v['LiH_m'], 2)] for k, v in o['dose'].items()])]
    return '\n'.join(s)+'\n'
